"""Fine-tune SmolLM2-135M on valid sequences generated by the tuned teacher."""

from __future__ import annotations

import argparse
import json
import random
import time
from pathlib import Path

import torch
from datasets import Dataset
from transformers import AutoModelForCausalLM, AutoTokenizer
from trl import SFTConfig, SFTTrainer

from train.formatting import messages

STUDENT = "HuggingFaceTB/SmolLM2-135M-Instruct"
REVISION = "12fd25f77366fa6b3b4b768ec3050bf629380bac"


def train(data_path: Path, output: Path, max_steps: int | None = None,
          seed: int = 19) -> dict:
    rows = [json.loads(line) for line in data_path.read_text().splitlines() if line]
    random.Random(seed).shuffle(rows)
    tokenizer = AutoTokenizer.from_pretrained(STUDENT, revision=REVISION)
    tokenizer.pad_token = tokenizer.eos_token
    records = []
    for item in rows:
        turns = messages(item["row"], include_answer=False)
        answer = {"role": "assistant", "content": json.dumps(
            item["teacher_output"], separators=(",", ":"), sort_keys=True)}
        if len(tokenizer.apply_chat_template([*turns, answer])) <= 1024:
            records.append({"prompt": turns, "completion": [answer]})
    if len(records) < 2:
        raise RuntimeError("too few student examples within 1024 tokens")
    cutoff = max(1, round(0.05 * len(records)))
    validation = Dataset.from_list(records[:cutoff])
    training = Dataset.from_list(records[cutoff:])
    device = "cuda" if torch.cuda.is_available() else (
        "mps" if torch.backends.mps.is_available() else "cpu")
    model = AutoModelForCausalLM.from_pretrained(
        STUDENT, revision=REVISION,
        dtype=torch.float16 if device != "cpu" else torch.float32,
        low_cpu_mem_usage=True,
    )
    options = SFTConfig(
        output_dir=str(output / "trainer"), seed=seed, num_train_epochs=2,
        max_steps=max_steps or -1, learning_rate=5e-5,
        per_device_train_batch_size=1, per_device_eval_batch_size=1,
        gradient_accumulation_steps=4, max_length=1024,
        completion_only_loss=True, packing=False,
        gradient_checkpointing=True, eval_strategy="epoch", save_strategy="no",
        logging_steps=20, logging_first_step=True, report_to="none",
        fp16=False, bf16=False,
    )
    trainer = SFTTrainer(model=model, args=options, train_dataset=training,
                         eval_dataset=validation, processing_class=tokenizer)
    started = time.perf_counter()
    outcome = trainer.train()
    duration = time.perf_counter() - started
    output.mkdir(parents=True, exist_ok=True)
    trainer.model.save_pretrained(output / "model")
    tokenizer.save_pretrained(output / "model")
    report = {"student": STUDENT, "revision": REVISION,
              "distill_data": str(data_path), "train_examples": len(training),
              "validation_examples": len(validation), "excluded_too_long": len(rows) - len(records),
              "steps_completed": trainer.state.global_step,
              "duration_seconds": duration, "train_loss": outcome.training_loss,
              "last_eval": next((item for item in reversed(trainer.state.log_history)
                                 if "eval_loss" in item), None)}
    (output / "metrics.json").write_text(json.dumps(report, indent=2) + "\n")
    return report


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--data", type=Path, default=Path("runs/distill_teacher.jsonl"))
    parser.add_argument("--output", type=Path, default=Path("runs/distilled_smollm2_135m"))
    parser.add_argument("--max-steps", type=int)
    args = parser.parse_args()
    print(json.dumps(train(args.data, args.output, args.max_steps), indent=2))
